import {availability} from './engine.js';
import {bookTotals,incomeValue,revenue} from './workbench.js';
export const COPY_FIELDS={amount:'包含金额（总开关）',initial:'初始现金',remaining:'剩余现金',delta:'现金变化',wechat:'微信收入',alipay:'支付宝收入',growth:'当天增值',planned:'拟购金额',actual:'实际金额',balances:'预算余额',note:'收入备注',time:'登记／购买／中奖时间',status:'完成／领取状态',details:'类别与待办明细',source:'预算来源与比例',summary:'收入汇总',title:'标题与名称'};
export function copyText(kind,row,w,options={},now=Date.now()){
 const f=Object.fromEntries(Object.keys(COPY_FIELDS).map(k=>[k,options[k]!==false])),out=[],money=n=>'¥'+(n/100).toFixed(2),time=t=>new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
 const line=(key,text)=>{if(f[key])out.push(text);};
 const item=i=>{line('title',i.name);if(f.amount){line('planned','拟购 '+money(i.planned));line('actual','实际 '+money(i.actual));}line('status',i.paid?'已完成／已购买':'未完成／待购买');if(i.paid)line('time','购买时间：'+time(i.paidAt));};
 if(kind==='income'){line('title','改日收入');if(f.summary&&f.amount){for(const [k,n] of [['total','总收入'],['month','本月收入'],['year','本年收入']])out.push(n+'：'+money(revenue(w,k,now)));}for(const r of row){line('time','登记时间：'+time(r.registeredAt));if(f.amount){for(const [key,label,value] of [['initial','初始现金',r.initial],['remaining','剩余现金',r.remaining],['delta','现金变化',r.remaining-r.initial],['wechat','微信',r.wechat],['alipay','支付宝',r.alipay],['growth','当天增值',incomeValue(r)]])line(key,label+' '+money(value));}if(r.note)line('note','备注：'+r.note);out.push('');}}
 if(kind==='book'){for(const b of row){const t=bookTotals(w,b,now);line('title',b.name);line('source',b.basis==='fixed'?'固定预算':({month:'本月收入',year:'本年收入',total:'总收入'})[b.basis]+' × '+b.percent/100+'%');if(f.balances)line('amount',`当前额度 ${money(t.allocation)} · 拟购后剩余 ${money(t.plannedRemaining)} · 实际剩余 ${money(t.actualRemaining)}`);if(f.details)for(const c of b.categories){line('title','类别：'+c.name);c.items.forEach(item);}out.push('');}}
 if(kind==='category'){line('title',row.name);if(f.amount)out.push('拟购合计 '+money(row.items.reduce((s,i)=>s+i.planned,0))+' · 实际已花 '+money(row.items.filter(i=>i.paid).reduce((s,i)=>s+i.actual,0)));if(f.details)row.items.forEach(item);}
 if(kind==='item')item(row);
 if(kind==='records'){line('title','中奖记录');for(const r of row){line('title',r.name+' · '+r.category);line('time',time(r.at));line('status',r.status==='pending'?'待领取':r.status==='abandoned'?'已放弃':'已领取');}}
 if(kind==='inventory'){line('title','库存看板');for(const p of row){line('title',p.name);line('amount',`概率 ${p.probability}% · 周上限 ${p.weekly??'不限'} · 月上限 ${p.monthly??'不限'} · 日上限 ${p.daily??'不限'}`);if(p.stats){line('amount',`累计领取 ${p.stats.used.total} · 本周领取 ${p.stats.used.weekly} · 本月领取 ${p.stats.used.monthly} · 今日领取 ${p.stats.used.daily} · 本周剩余 ${p.stats.remaining??'不限'}`);line('status',p.stats.available?'可抽取':p.stats.reason);}}}
 return out.join('\n').trim();
}
export function installCopy(ctx){
 let pending=false;
 const write=async text=>{if(!text){ctx.toast('当前选项下没有可复制内容，请在设置中勾选信息');return;}try{if(window.BeanAndroid?.copyText)window.BeanAndroid.copyText(text);else {try{await navigator.clipboard.writeText(text);}catch{const a=document.createElement('textarea');a.value=text;document.body.append(a);a.select();const ok=document.execCommand('copy');a.remove();if(!ok)throw Error('复制失败');}}ctx.toast('已复制，可以粘贴分享');}catch{ctx.toast('复制失败，请重试');}};
 function add(parent,kind,get){if(!parent||parent.querySelector(':scope > .copy-action'))return;const b=document.createElement('button');b.type='button';b.className='small-button copy-action';b.textContent='一键复制';b.onclick=e=>{e.stopPropagation();const s=ctx.state(),w=s.workbench||{incomes:[],books:[]};write(copyText(kind,get(w,s),w,w.copyFields));};parent.append(b);}
 function attach(){const page=document.querySelector('.nav-item.active')?.dataset.page,s=ctx.state();if(!s)return;const w=s.workbench||{incomes:[],books:[]};
 if(page==='settings'&&!document.querySelector('#copy-settings')){const card=document.createElement('section');card.id='copy-settings';card.className='card owner-card';card.innerHTML='<h2>一键复制内容设置</h2><p class="help">勾选允许带上的信息，取消后所有复制按钮都会省略该项。复制不会包含密码或安全问题。</p>'+Object.entries(COPY_FIELDS).map(([k,n])=>`<label class="copy-option"><input type="checkbox" data-copy-field="${k}" ${w.copyFields?.[k]===false?'':'checked'}>${n}</label>`).join('');card.onchange=()=>ctx.safe(async()=>{const fields=Object.fromEntries([...card.querySelectorAll('input')].map(i=>[i.dataset.copyField,i.checked]));await ctx.act({type:'workbench:preferences',fields});ctx.toast('复制内容设置已保存');});ctx.content.prepend(card);}
 if(page==='income'){add(document.querySelector('.page-heading'),'income',w=>w.incomes);document.querySelectorAll('[data-edit-income]').forEach(b=>add(b.parentElement,'income',w=>w.incomes.filter(r=>r.id===b.dataset.editIncome)));}
 if(page==='budget'){const b=w.books.find(b=>b.categories.some(c=>document.querySelector(`[data-add-item="${c.id}"]`)))||w.books.find(b=>document.querySelector('.book-title')?.textContent===b.name);add(document.querySelector('.page-heading'),'book',w=>b?w.books.filter(x=>x.id===b.id):w.books);document.querySelectorAll('[data-book]').forEach(el=>add(el.parentElement,'book',w=>w.books.filter(b=>b.id===el.dataset.book)));document.querySelectorAll('[data-collapse]').forEach(el=>add(el.parentElement,'category',w=>w.books.flatMap(b=>b.categories).find(c=>c.id===el.dataset.collapse)));document.querySelectorAll('[data-edit-item]').forEach(el=>add(el.closest('.todo-row'),'item',w=>w.books.flatMap(b=>b.categories.flatMap(c=>c.items)).find(i=>i.id===el.dataset.editItem)));}
 if(page==='draw'&&s.session)add(document.querySelector('.page-heading'),'records',(_,s)=>[{...s.session,at:s.session.claimedAt||s.session.drawnAt}]);
 if(page==='records')add(document.querySelector('.page-heading'),'records',(_,s)=>s.records.filter(r=>r.date===document.querySelector('#record-date')?.value&&(!document.querySelector('#category')?.value||r.category===document.querySelector('#category').value)).sort((a,b)=>a.at.localeCompare(b.at)));
 if(page==='inventory')add(document.querySelector('.page-heading'),'inventory',(_,s)=>s.prizes.map(p=>({...p,stats:availability(s,p)})));
 }
 const observer=new MutationObserver(()=>{if(pending)return;pending=true;queueMicrotask(()=>{observer.disconnect();attach();observer.observe(ctx.content,{subtree:true,childList:true});pending=false;});});observer.observe(ctx.content,{subtree:true,childList:true});attach();
}
